def solve(matrix):
    """Return the elements of the rectangular matrix in clockwise spiral order.
    If matrix is empty or contains no rows, return []
    """
    if not matrix:
        return []
    # assume rectangular: all rows have same length
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    res = []
    while top <= bottom and left <= right:
        # traverse left to right on top row
        for c in range(left, right + 1):
            res.append(matrix[top][c])
        top += 1
        # traverse top to bottom on right column
        for r in range(top, bottom + 1):
            res.append(matrix[r][right])
        right -= 1
        if top <= bottom:
            # traverse right to left on bottom row
            for c in range(right, left - 1, -1):
                res.append(matrix[bottom][c])
            bottom -= 1
        if left <= right:
            # traverse bottom to top on left column
            for r in range(bottom, top - 1, -1):
                res.append(matrix[r][left])
            left += 1
    return res

