    """Return the number of prime numbers strictly less than n.
    Handles non‑positive inputs and non‑int types gracefully.
    """
    try:
        n = int(n)
    except Exception:
        return 0
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    import math
    limit = n - 1
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            # avoid negative length slice
            if start < n:
                sieve[start:n:step] = b'\x00' * ((n - start - 1) // step + 1)
    return int(sieve.count(1))"}

