def solve(n, b):
    """Convert integer n to string representation in base b (2-36).
    Uses digits 0-9 and letters a-z for values 10-35. Handles negative numbers.
    """
    if b < 2 or b > 36:
        raise ValueError("Base out of range")
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
