def solve(a,b):
    """Compute Levenshtein edit distance between strings a and b."""
    n,m = len(a), len(b)
    # Ensure a is the shorter for less space
    if n > m:
        a,b = b,a
        n,m = m,n
    # dp[j] = distance for a[:i] and b[:j]
    previous = list(range(m+1))
    for i in range(1, n+1):
        current = [i] + [0]*m
        for j in range(1, m+1):
            if a[i-1] == b[j-1]:
                cost = 0
            else:
                cost = 1
            current[j] = min(
                previous[j] + 1,      # deletion
                current[j-1] + 1,     # insertion
                previous[j-1] + cost  # substitution
            )
        previous = current
    return previous[m]

