def solve(grid):
    if not grid:
        return -1
    n = len(grid)
    m = len(grid[0])
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return -1
    from collections import deque
    q = deque()
    q.append((0, 0, 0))  # steps
    visited = [[False]*m for _ in range(n)]
    visited[0][0] = True
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    while q:
        x,y,dist = q.popleft()
        if x == n-1 and y == m-1:
            return dist
        for dx,dy in dirs:
            nx,ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == 0:
                visited[nx][ny] = True
                q.append((nx,ny,dist+1))
    return -1

