def solve(s):
    """Convert a Roman numeral string *s* to its integer value.
    Supports standard symbols I, V, X, L, C, D, M with subtractive notation.
    """
    if not s:
        return 0
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50,
              'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    # Iterate from right to left, adding or subtracting based on previous value.
    for ch in reversed(s.upper()):
        val = values.get(ch, 0)
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total

